ECO_MONTEE = [0.4, 0.7, 0.9, 1.0, 1.0]


def tri(b, c, h, **kw):
    d = {'forme': 'tri', 'bas': b, 'central': c, 'haut': h}
    d.update(kw)
    return d


def med(b, c, h, **kw):
    d = {'forme': 'med', 'bas': b, 'central': c, 'haut': h}
    d.update(kw)
    return d


def eco(id_, theme, chap, lib, cit, an1_rn, annonce, bas, c, haut, interp, contrainte, hyps, montee=None, lam=0.5):
    """Économie ou recette annoncée : montant RN = plafond (haut) ; médiane = ce qui est réalisable selon nos hypothèses (contrainte juridique ou pratique nommée dans `contrainte`)."""
    return dict(id=id_, theme=theme, chapitre=chap, libelle=lib, citation=cit, lien=DOSSIER, sens='recette', levier='cout_unitaire', valeur=med(bas, c, haut), annonce=annonce, an1_rn=an1_rn, montee=montee or ECO_MONTEE,
                facteur='cout', **{'lambda': lam}, interpretation=interp, contrainte=contrainte,
                hypotheses=[('H-RN-%s' % id_, "Montant annoncé : %s Md€ (2027 : %s). Fourchette retenue : plancher %s, médiane %s, plafond %s Md€ (convention : la médiane est notre estimation réalisable)." % (annonce, an1_rn, bas, c, haut), SRC_RN, 'D', COI_RN)] + hyps)


def cout_rn(id_, theme, chap, lib, cit, m, interp='', bas=0.95, haut=1.15, hyps=(), lam=0.3, montee=None):
    """Baisse d'impôt ou dépense nouvelle chiffrée par le RN seul : coût certain une fois votée ; valeur centrale = montant du RN, fourchette 0,95 à 1,15 fois (convention, sans source)."""
    d = dict(id=id_, theme=theme, chapitre=chap, libelle=lib, citation=cit, lien=DOSSIER, sens='depense', levier='cout_unitaire', valeur=tri(bas * m, m, haut * m), annonce=m, an1_rn=m, an1=m, facteur='cout', **{'lambda': lam},
             interpretation=interp, hypotheses=[('H-RN-%s' % id_, "Montant du RN : %s Md€ ; fourchette %s à %s fois (convention, sans source)." % (m, bas, haut), SRC_RN, 'D', COI_RN)] + list(hyps))
    if montee:
        d['montee'] = montee
        d.pop('an1')
    return d


