 # ------------------------------------------------------------------ Union européenne
 eco('U01', 'Union européenne', 'Europe', "Baisse unilatérale de la contribution de la France au budget de l'Union européenne", "« Baisse de la contribution de la France à l'Union européenne 8,897 » (13,1 Md€ en 2031 avec les droits de douane)", 8.9, 13.1, 0.0, 0.8, 8.9,
     "Le prélèvement sur recettes pour 2027 est de 30,9 Md€ (Localtis, 15/10/2026) ; la contribution NETTE de la France est de l'ordre de 9,5 Md€ (même source). Il est fixé par la décision sur les ressources propres, adoptée à l'unanimité et ratifiée par chaque État membre : aucun mécanisme ne permet de le réduire seul (Institut de l'Entreprise). Une baisse unilatérale serait un manquement au droit de l'UE (art. 311 TFUE, procédure en manquement, retenues sur les versements de l'Union) ; une sortie ou une renégociation relève d'un autre scénario. Médiane 0,8 Md€ : les marges d'une négociation (rabais, ressources propres nouvelles, utilisation de l'amende Google, dont le Premier ministre actuel demande qu'elle réduise les contributions) ; plafond 8,9 Md€ (annonce 2027). Le budget pluriannuel 2028-2034 proposé par la Commission ferait monter la contribution à environ 35 Md€ par an (estimation de la direction du Budget) : une hausse évitée n'est pas une économie par rapport au droit actuel, elle n'est pas comptée.",
     "Traités (art. 311 TFUE : ressources propres arrêtées à l'unanimité, approbation par les États membres selon leurs règles constitutionnelles), décision (UE, Euratom) 2020/2053 ; manquement (art. 258-260 TFUE)", [('H-UE', "PSR-UE 2027 : 30,9 Md€ ; contribution nette de la France : environ 9,5 Md€ hors NextGenerationEU (2e contributeur net) ; budget 2028-2034 proposé : environ 35 Md€ par an de contribution moyenne (estimation de la direction du Budget).", "Localtis (Banque des Territoires), 15/10/2026 (%s), lu le 08/11/2026" % BT_URL, 'B', 'groupe Caisse des dépôts, établissement public'), H_IDEP_NON("Baisse unilatérale de la contribution : 13,1 Md€ en 2031, soit 42 % du prélèvement attendu en 2027 et plus que la contribution nette ; catégorie C (juridiquement fragile).")], lam=0.4),
 eco('U02', 'Union européenne', 'Europe', "Restitution à la France de sa part des droits de douane collectés par l'UE", "« Rendre à la France sa part des droits de douane collectés par l'UE 2,200 »", 2.2, 2.2, 0.0, 0.2, 2.2,
     "Les droits de douane sont une ressource propre traditionnelle de l'Union (la France en retient 25 % pour frais de perception) : même décision unanime que U01. Médiane 0,2 Md€.", "Décision (UE, Euratom) 2020/2053, art. 311 TFUE", [], lam=0.4),
